        val d_resolution = Bincode.readOption(bytes, cursor) { b1, c1 -> readResolution(b1, c1) }; cursor = d_resolution.consumed
        val resolution = d_resolution.value
        val d_flash = readFlashMode(bytes, cursor); cursor = d_flash.consumed
        val flash = d_flash.value
        return Bincode.Decoded(StillCaptureRequest(pixelFormat = pixelFormat, resolution = resolution, flash = flash), cursor)
    }

    override fun writeStillCaptureRequest(out: ByteArrayOutputStream, value: StillCaptureRequest) {
        writePixelFormat(out, value.pixelFormat)
        Bincode.writeOption(out, value.resolution) { s1, v1 -> writeResolution(s1, v1) }
        writeFlashMode(out, value.flash)
    }

    override fun readStillPhoto(bytes: ByteArray, offset: Int): Bincode.Decoded<StillPhoto> {
        var cursor = offset
        val d_resolution = readResolution(bytes, cursor); cursor = d_resolution.consumed
        val resolution = d_resolution.value
        val d_rotationDegrees = Bincode.readU16(bytes, cursor); cursor = d_rotationDegrees.consumed
        val rotationDegrees = d_rotationDegrees.value
        val d_pixelFormat = readPixelFormat(bytes, cursor); cursor = d_pixelFormat.consumed
        val pixelFormat = d_pixelFormat.value
        val d_bytes_ = Bincode.readBytes(bytes, cursor); cursor = d_bytes_.consumed
        val bytes_ = d_bytes_.value
        val d_timestampNs = Bincode.readU64(bytes, cursor); cursor = d_timestampNs.consumed
        val timestampNs = d_timestampNs.value
        return Bincode.Decoded(StillPhoto(resolution = resolution, rotationDegrees = rotationDegrees, pixelFormat = pixelFormat, bytes = bytes_, timestampNs = timestampNs), cursor)
    }

    override fun writeStillPhoto(out: ByteArrayOutputStream, value: StillPhoto) {
        writeResolution(out, value.resolution)
        Bincode.writeU16(out, value.rotationDegrees)
        writePixelFormat(out, value.pixelFormat)
        Bincode.writeBytes(out, value.bytes)
        Bincode.writeU64(out, value.timestampNs)
    }

    override fun readCameraError(bytes: ByteArray, offset: Int): Bincode.Decoded<CameraError> {
        var cursor = offset
        val disc = Bincode.readEnumDiscriminant(bytes, cursor)
        cursor = disc.consumed
        return when (disc.value) {
            0 -> Bincode.Decoded(CameraError.PermissionDenied, cursor)
            1 -> {
                val d_inner = Bincode.readString(bytes, cursor); cursor = d_inner.consumed
                val inner = d_inner.value
                Bincode.Decoded(CameraError.DeviceNotFound(inner) as CameraError, cursor)
            }
            2 -> Bincode.Decoded(CameraError.FormatUnsupported, cursor)
            3 -> Bincode.Decoded(CameraError.ConcurrencyUnsupported, cursor)
            4 -> Bincode.Decoded(CameraError.SessionClosed, cursor)
            5 -> Bincode.Decoded(CameraError.Interrupted, cursor)
            6 -> {
                val d_inner = Bincode.readString(bytes, cursor); cursor = d_inner.consumed
                val inner = d_inner.value
                Bincode.Decoded(CameraError.Backend(inner) as CameraError, cursor)
            }
            else -> throw Bincode.DecodeException("CameraError: unknown discriminant ${disc.value}")
        }
    }

    override fun writeCameraError(out: ByteArrayOutputStream, value: CameraError) {
        when (value) {
            CameraError.PermissionDenied -> Bincode.writeEnumDiscriminant(out, 0)
            is CameraError.DeviceNotFound -> {
                Bincode.writeEnumDiscriminant(out, 1)
                Bincode.writeString(out, value.value)
            }
            CameraError.FormatUnsupported -> Bincode.writeEnumDiscriminant(out, 2)
            CameraError.ConcurrencyUnsupported -> Bincode.writeEnumDiscriminant(out, 3)
            CameraError.SessionClosed -> Bincode.writeEnumDiscriminant(out, 4)
            CameraError.Interrupted -> Bincode.writeEnumDiscriminant(out, 5)
            is CameraError.Backend -> {
                Bincode.writeEnumDiscriminant(out, 6)
                Bincode.writeString(out, value.value)
            }
        }
    }

    override fun readNativeHandleId(bytes: ByteArray, offset: Int): Bincode.Decoded<NativeHandleId> {
        return Bincode.readVarintU64(bytes, offset)
    }

    override fun writeNativeHandleId(out: ByteArrayOutputStream, value: NativeHandleId) {
        Bincode.writeU64(out, value.toULong())
    }
}
